import{_ as t,a0 as d,w as o,s as r,ao as l,I as a,x as n,a1 as i,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Linux 中查看系统硬件制造商、型号和序列号 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中查看系统硬件制造商、型号和序列号 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中查看系统硬件制造商、型号和序列号 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中查看系统硬件制造商、型号和序列号 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180426 How To Check System Hardware Manufacturer, Model And Serial Number In Linux","title":"如何在 Linux 中查看系统硬件制造商、型号和序列号","tag":"201808","desc":""},"relativePath":"201808/20180426 How To Check System Hardware Manufacturer, Model And Serial Number In Linux.md","filePath":"[post].md"}'),u={name:"201808/20180426 How To Check System Hardware Manufacturer, Model And Serial Number In Linux.md"};function c(h,s,m,g,b,k){const e=d("Link");return o(),r("div",null,[s[27]||(s[27]=l(`<h1 id="如何在-linux-中查看系统硬件制造商、型号和序列号" tabindex="-1">如何在 Linux 中查看系统硬件制造商、型号和序列号 <a class="header-anchor" href="#如何在-linux-中查看系统硬件制造商、型号和序列号" aria-label="Permalink to “如何在 Linux 中查看系统硬件制造商、型号和序列号”">​</a></h1><p>对于 Linux 图形界面用户和 Windows 用户来说获取系统硬件信息都不算问题，但是对命令行用户来说想要获取这些细节时有点儿麻烦。</p><p>甚至我们中的大多数都不知道获取这些信息最好的命令是什么。Linux 中有许多可用的工具集来获取诸如制造商、型号和序列号等硬件信息。</p><p>在这里我尝试写下获取这些细节的可能的方式，你可以挑选一种最好用的。</p><p>你必须知道所有这些信息，因为当你向硬件制造商提交任何硬件问题时，你会需要它们。</p><p>这可以通过 6 种方法来实现，下面我来演示一下怎么做。</p><h3 id="方法一-使用-dmidecode-命令" tabindex="-1">方法一：使用 dmidecode 命令 <a class="header-anchor" href="#方法一-使用-dmidecode-命令" aria-label="Permalink to “方法一：使用 dmidecode 命令”">​</a></h3><p><code>dmidecode</code> 是一个读取电脑 DMI（<ruby>桌面管理接口<rt>Desktop Management Interface</rt></ruby>）表内容并且以人类可读的格式显示系统硬件信息的工具。（也有人说是读取 SMBIOS —— <ruby>系统管理 BIOS<rt>System Management BIOS</rt></ruby>）</p><p>这个表包含系统硬件组件的说明，也包含如序列号、制造商、发布日期以及 BIOS 修订版本号等其它有用的信息。</p><p>DMI 表不仅描述了当前的系统构成，还可以报告可能的升级信息（比如可以支持的最快的 CPU 或者最大的内存容量）。</p><p>这将有助于分析你的硬件兼容性，比如是否支持最新版本的程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dmidecode -t system</span></span>
<span class="line"><span></span></span>
<span class="line"><span># dmidecode 2.12</span></span>
<span class="line"><span># SMBIOS entry point at 0x7e7bf000</span></span>
<span class="line"><span>SMBIOS 2.7 present.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Handle 0x0024, DMI type 1, 27 bytes</span></span>
<span class="line"><span>System Information</span></span>
<span class="line"><span> Manufacturer: IBM</span></span>
<span class="line"><span> Product Name: System x2530 M4: -[1214AC1]-</span></span>
<span class="line"><span> Version: 0B</span></span>
<span class="line"><span> Serial Number: MK2RL11</span></span>
<span class="line"><span> UUID: 762A99BF-6916-450F-80A6-B2E9E78FC9A1</span></span>
<span class="line"><span> Wake-up Type: Power Switch</span></span>
<span class="line"><span> SKU Number: Not Specified</span></span>
<span class="line"><span> Family: System X</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Handle 0x004B, DMI type 12, 5 bytes</span></span>
<span class="line"><span>System Configuration Options</span></span>
<span class="line"><span> Option 1: JP20 pin1-2: TPM PP Disable, pin2-3: TPM PP Enable</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Handle 0x004D, DMI type 32, 20 bytes</span></span>
<span class="line"><span>System Boot Information</span></span>
<span class="line"><span> Status: No errors detected</span></span></code></pre></div>`,12)),a("p",null,[s[1]||(s[1]=a("strong",null,"推荐阅读：",-1)),s[2]||(s[2]=n()),i(e,{href:"https://www.2daygeek.com/dmidecode-get-print-display-check-linux-system-hardware-information/"},{default:p(()=>[...s[0]||(s[0]=[n("Dmidecode –– 获取 Linux 系统硬件信息的简单方式",-1)])]),_:1})]),s[28]||(s[28]=l(`<h3 id="方法二-使用-inxi-命令" tabindex="-1">方法二：使用 inxi 命令 <a class="header-anchor" href="#方法二-使用-inxi-命令" aria-label="Permalink to “方法二：使用 inxi 命令”">​</a></h3><p><code>inxi</code> 是 Linux 上查看硬件信息的一个灵巧的小工具，它提供了大量的选项来获取所有硬件信息，这是我在现有的其它 Linux 工具集里所没见到过的。它是从 locsmif 编写的古老的但至今看来都异常灵活的 <code>infobash</code> fork 出来的。</p><p><code>inxi</code> 是一个可以快速显示系统硬件、CPU、驱动、Xorg、桌面、内核、GCC 版本、进程、内存使用以及大量其它有用信息的脚本，也可以用来做技术支持和调试工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># inxi -M</span></span>
<span class="line"><span>Machine: Device: server System: IBM product: N/A v: 0B serial: MK2RL11</span></span>
<span class="line"><span> Mobo: IBM model: 00Y8494 serial: 37M17D UEFI: IBM v: -[VVE134MUS-1.50]- date: 08/30/2013</span></span></code></pre></div>`,4)),a("p",null,[s[4]||(s[4]=a("strong",null,"推荐阅读：",-1)),s[5]||(s[5]=n()),i(e,{href:"https://www.2daygeek.com/inxi-system-hardware-information-on-linux/"},{default:p(()=>[...s[3]||(s[3]=[n("inxi —— 一个很棒的查看 Linux 硬件信息的工具",-1)])]),_:1})]),s[29]||(s[29]=l(`<h3 id="方法三-使用-lshw-命令" tabindex="-1">方法三：使用 lshw 命令 <a class="header-anchor" href="#方法三-使用-lshw-命令" aria-label="Permalink to “方法三：使用 lshw 命令”">​</a></h3><p><code>lshw</code>（指<ruby>硬件监听器<rt>Hardware Lister</rt></ruby>）是一个小巧灵活的工具，可以生成如内存配置、固件版本、主板配置、CPU 版本和速度、缓存配置、USB、网卡、显卡、多媒体、打印机以及总线速度等机器中各种硬件组件的详细报告。</p><p>它通过读取 <code>/proc</code> 目录下各种文件的内容和 DMI 表来生成硬件信息。</p><p><code>lshw</code> 必须以超级用户的权限运行来检测完整的硬件信息，否则它只汇报部分信息。<code>lshw</code> 里有一个叫做 <code>class</code> 的特殊选项，它可以以详细的模式显示特定的硬件信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lshw -C system</span></span>
<span class="line"><span>enal-dbo01t</span></span>
<span class="line"><span> description: Blade</span></span>
<span class="line"><span> product: System x2530 M4: -[1214AC1]-</span></span>
<span class="line"><span> vendor: IBM</span></span>
<span class="line"><span> version: 0B</span></span>
<span class="line"><span> serial: MK2RL11</span></span>
<span class="line"><span> width: 64 bits</span></span>
<span class="line"><span> capabilities: smbios-2.7 dmi-2.7 vsyscall32</span></span>
<span class="line"><span> configuration: boot=normal chassis=enclosure family=System X uuid=762A99BF-6916-450F-80A6-B2E9E78FC9A1</span></span></code></pre></div>`,5)),a("p",null,[s[7]||(s[7]=a("strong",null,"推荐阅读：",-1)),s[8]||(s[8]=n()),i(e,{href:"https://www.2daygeek.com/lshw-find-check-system-hardware-information-details-linux/"},{default:p(()=>[...s[6]||(s[6]=[n("LSHW (Hardware Lister) –– 获取 Linux 硬件信息的灵巧的小工具",-1)])]),_:1})]),s[30]||(s[30]=l(`<h3 id="方法四-使用-sys-文件系统" tabindex="-1">方法四：使用 /sys 文件系统 <a class="header-anchor" href="#方法四-使用-sys-文件系统" aria-label="Permalink to “方法四：使用 /sys 文件系统”">​</a></h3><p>内核在 <code>/sys</code> 目录下的文件中公开了一些 DMI 信息。因此，我们可以通过如下方式运行 <code>grep</code> 命令来轻易地获取机器类型。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grep &quot;&quot; /sys/class/dmi/id/[pbs]*</span></span></code></pre></div><p>或者，可以使用 <code>cat</code> 命令仅打印出特定的详细信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /sys/class/dmi/id/board_vendor</span></span>
<span class="line"><span>IBM</span></span>
<span class="line"><span></span></span>
<span class="line"><span># cat /sys/class/dmi/id/product_name</span></span>
<span class="line"><span>System x2530 M4: -[1214AC1]-</span></span>
<span class="line"><span></span></span>
<span class="line"><span># cat /sys/class/dmi/id/product_serial</span></span>
<span class="line"><span>MK2RL11</span></span>
<span class="line"><span></span></span>
<span class="line"><span># cat /sys/class/dmi/id/bios_version</span></span>
<span class="line"><span>-[VVE134MUS-1.50]-</span></span></code></pre></div><h3 id="方法五-使用-dmesg-命令" tabindex="-1">方法五：使用 dmesg 命令 <a class="header-anchor" href="#方法五-使用-dmesg-命令" aria-label="Permalink to “方法五：使用 dmesg 命令”">​</a></h3><p><code>dmesg</code> 命令是在 Linux 上 <code>syslogd</code> 或 <code>klogd</code> 启动前用来记录内核消息（启动阶段的消息）的。它通过读取内核的环形缓冲区来获取数据。在排查问题或只是尝试获取系统硬件信息时，<code>dmesg</code> 非常有用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dmesg | grep -i DMI</span></span>
<span class="line"><span>DMI: System x2530 M4: -[1214AC1]-/00Y8494, BIOS -[VVE134MUS-1.50]- 08/30/2013</span></span></code></pre></div><h3 id="方法六-使用-hwinfo-命令" tabindex="-1">方法六：使用 hwinfo 命令 <a class="header-anchor" href="#方法六-使用-hwinfo-命令" aria-label="Permalink to “方法六：使用 hwinfo 命令”">​</a></h3><p><code>hwinfo</code>（<ruby>硬件信息<rt>hardware information</rt></ruby>）是另一个很棒的工具，用于检测当前系统存的硬件，并以人类可读的方式显示各种硬件模块的详细信息。</p><p>它报告关于 CPU、内存、键盘、鼠标、显卡、声卡、存储、网络接口、磁盘、分区、BIOS 以及桥接器等信息。它可以比其它像 <code>lshw</code>、<code>dmidecode</code> 或 <code>inxi</code> 等工具显示更为详细的信息。</p><p><code>hwinfo</code> 使用 libhd 库 <code>libhd.so</code> 来收集系统上的硬件信息。该工具是为 openSuse 特别设计的，后来其它发行版也将它包含在其官方仓库中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># hwinfo | egrep &quot;system.hardware.vendor|system.hardware.product&quot;</span></span>
<span class="line"><span> system.hardware.vendor = &#39;IBM&#39;</span></span>
<span class="line"><span> system.hardware.product = &#39;System x2530 M4: -[1214AC1]-&#39;</span></span></code></pre></div>`,13)),a("p",null,[s[10]||(s[10]=a("strong",null,"推荐阅读：",-1)),s[11]||(s[11]=n()),i(e,{href:"https://www.2daygeek.com/hwinfo-check-display-detect-system-hardware-information-linux/"},{default:p(()=>[...s[9]||(s[9]=[n("hwinfo (Hardware Info) –– 一款灵活的检测 Linux 系统硬件信息的工具",-1)])]),_:1})]),s[31]||(s[31]=a("hr",null,null,-1)),a("p",null,[s[13]||(s[13]=n("via: ",-1)),i(e,{href:"https://www.2daygeek.com/how-to-check-system-hardware-manufacturer-model-and-serial-number-in-linux/"},{default:p(()=>[...s[12]||(s[12]=[n("https://www.2daygeek.com/how-to-check-system-hardware-manufacturer-model-and-serial-number-in-linux/",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=n("作者：",-1)),i(e,{href:"https://www.2daygeek.com/author/vinoth/"},{default:p(()=>[...s[14]||(s[14]=[n("VINOTH KUMAR",-1)])]),_:1}),s[19]||(s[19]=n(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[15]||(s[15]=[n("lujun9972",-1)])]),_:1}),s[20]||(s[20]=n(" 译者：",-1)),i(e,{href:"https://github.com/icecoobe"},{default:p(()=>[...s[16]||(s[16]=[n("icecoobe",-1)])]),_:1}),s[21]||(s[21]=n(" 校对：",-1)),i(e,{href:"https://github.com/pityonline"},{default:p(()=>[...s[17]||(s[17]=[n("pityonline",-1)])]),_:1})]),a("p",null,[s[24]||(s[24]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[22]||(s[22]=[n("LCTT",-1)])]),_:1}),s[25]||(s[25]=n(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[23]||(s[23]=[n("Linux中国",-1)])]),_:1}),s[26]||(s[26]=n(" 荣誉推出",-1))])])}const w=t(u,[["render",c]]);export{x as __pageData,w as default};
